// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;

    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }

    function testFuzz_property(uint8 roleSeed, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        bytes32 role = roleSeed % 2 == 0 ? c.PROPOSER_ROLE() : c.EXECUTOR_ROLE();

        // deployer (this contract) holds TIMELOCK_ADMIN_ROLE, admin of both roles
        c.grantRole(role, actor);
        assertTrue(c.hasRole(role, actor));

        vm.prank(actor);
        c.renounceRole(role, actor);

        assertTrue(!c.hasRole(role, actor));
    }
}
